import{_ as t,o as i,c as a,a2 as s}from"./chunks/framework.vLhlLNVn.js";const o="data:image/svg+xml;base64,",p=JSON.parse('{"title":"Managing devices","description":"","frontmatter":{"order":5,"adapter":"wled","editLink":"https://github.com/DrozmotiX/ioBroker.wled/edit/main/docs/en/02.anleitungen/05.geraete-verwalten.md"},"headers":[],"relativePath":"adapter/wled/anleitungen/geraete-verwalten.md","filePath":"adapter/wled/anleitungen/geraete-verwalten.md","lastUpdated":null}'),d={name:"adapter/wled/anleitungen/geraete-verwalten.md"};function n(h,e,l,c,r,I){return i(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="managing-devices" tabindex="-1">Managing devices <a class="header-anchor" href="#managing-devices" aria-label="Permalink to &quot;Managing devices&quot;">​</a></h1><p><a id="remove-wled-device-adapter"></a></p><h2 id="how-do-i-remove-a-wled-device-from-the-adapter" tabindex="-1">How do I remove a WLED device from the adapter? <a class="header-anchor" href="#how-do-i-remove-a-wled-device-from-the-adapter" aria-label="Permalink to &quot;How do I remove a WLED device from the adapter?&quot;">​</a></h2><p><strong>In short:</strong> In Admin, you delete a device under &quot;Devices&quot; with the trash can icon, or in the instance settings with the red button in the &quot;Remove&quot; column. The adapter then removes all states of the device and stops its connection and timers. If the device is still running in your network, the adapter finds it again via Bonjour and creates it anew.</p><h3 id="how-to-do-it-in-the-device-manager" tabindex="-1">How to do it: in the device manager <a class="header-anchor" href="#how-to-do-it-in-the-device-manager" aria-label="Permalink to &quot;How to do it: in the device manager&quot;">​</a></h3><ol><li>In Admin, open the &quot;Devices&quot; tab and select the instance <code>wled.&lt;instance&gt;</code>.</li><li>Click the trash can icon next to the device (&quot;Delete this device&quot;).</li><li>Confirm the question &quot;Do you really want to delete the device &lt;device&gt;?&quot;.</li><li>The device disappears from the list. The log shows <code>&lt;MAC&gt; deleted</code>.</li></ol><h3 id="how-to-do-it-in-the-instance-settings" tabindex="-1">How to do it: in the instance settings <a class="header-anchor" href="#how-to-do-it-in-the-instance-settings" aria-label="Permalink to &quot;How to do it: in the instance settings&quot;">​</a></h3><ol><li>In Admin, open the settings of <code>wled.&lt;instance&gt;</code> under &quot;Instances&quot;.</li><li>In the device table, click the red button with the trash can icon in the &quot;Remove&quot; column.</li><li>The dialog &quot;Delete device confirmation&quot; shows the name and IP address. Click &quot;Delete Device&quot;.</li><li>The message &quot;Device deleted successfully&quot; confirms the deletion. If something goes wrong, &quot;Failed to delete device&quot; appears.</li></ol><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>When deleting, the adapter removes the device object <code>wled.&lt;instance&gt;.&lt;MAC&gt;</code> with all states below it. Scripts, VIS views and aliases that point to these states will then point to nothing. If the adapter creates the device again later, the states are recreated under the same MAC.</p></div><h3 id="what-the-adapter-cleans-up-when-you-delete-a-device" tabindex="-1">What the adapter cleans up when you delete a device <a class="header-anchor" href="#what-the-adapter-cleans-up-when-you-delete-a-device" aria-label="Permalink to &quot;What the adapter cleans up when you delete a device&quot;">​</a></h3><p>For that device, the adapter stops the watchdog and the timers, closes the WebSocket connection and forgets the device. This also happens if you delete the device object <code>wled.&lt;instance&gt;.&lt;MAC&gt;</code> directly in the &quot;Objects&quot; tab. The log then shows <code>Device &lt;MAC&gt; was deleted from object tree, cleaning up backend processes and objects</code>.</p><p>If the adapter doesn&#39;t know the device when you delete it in the &quot;Objects&quot; tab, for example because it was never connected, it reports <code>Device &lt;MAC&gt; not found in devices array, cannot clean up backend processes and objects</code>. The objects are deleted anyway; you can ignore the warning.</p><h3 id="why-does-the-deleted-device-come-back" tabindex="-1">Why does the deleted device come back? <a class="header-anchor" href="#why-does-the-deleted-device-come-back" aria-label="Permalink to &quot;Why does the deleted device come back?&quot;">​</a></h3><p>The adapter looks for WLED devices via Bonjour (mDNS). The search starts when the adapter starts and when you click &quot;Discover new devices&quot; in the &quot;Devices&quot; tab. If a device the adapter doesn&#39;t know answers, the adapter creates it anew. A deleted device that is still switched on in your network therefore reappears. There is no list that lets you exclude individual devices from the search.</p><p>So only delete a device once you no longer use it or have taken it off the network.</p><p><img src="'+o+'" alt="Flow: You delete the device in the &quot;Devices&quot; tab, in the instance settings, in the &quot;Objects&quot; tab or from a script. The adapter deletes the states and stops the watchdog, timers and WebSocket. If the device is still running in the network, Bonjour finds it again when the adapter starts or on &quot;Discover new devices&quot;, and the adapter creates it anew under the same MAC."></p><h3 id="delete-a-device-from-a-script" tabindex="-1">Delete a device from a script <a class="header-anchor" href="#delete-a-device-from-a-script" aria-label="Permalink to &quot;Delete a device from a script&quot;">​</a></h3><p>With <code>sendTo</code> you delete a device by its IP address. The answer is <code>success</code> or <code>failed</code>:</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendTo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;wled.0&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;deleteDevice&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;192.168.x.y&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, (</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`Delete device: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">result</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><p>If the adapter can&#39;t find a device with this IP address, the log shows <code>Device with IP 192.168.x.y not found</code> and the answer is <code>failed</code>.</p><h3 id="older-versions" tabindex="-1">Older versions <a class="header-anchor" href="#older-versions" aria-label="Permalink to &quot;Older versions&quot;">​</a></h3><p><strong>Up to v0.9.2:</strong> In the instance settings you can&#39;t delete a device that has been offline since the adapter started. &quot;Failed to delete device&quot; appears, and the log shows <code>Device with IP 192.168.x.y not found</code>. In that case, delete the device in the &quot;Devices&quot; tab or in the &quot;Objects&quot; tab.</p><p><strong>From v0.9.3:</strong> Deleting in the instance settings also works for devices that are offline (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/787" target="_blank" rel="noreferrer">#787</a>). For this, the adapter also looks for the device in the object tree.</p><p><strong>Up to v0.9.2:</strong> In the &quot;Devices&quot; tab, the dialog doesn&#39;t wait for the result and doesn&#39;t show an error. For instances from <code>wled.10</code> upwards, deleting fails there. Use the &quot;Objects&quot; tab instead.</p><p><strong>From v0.9.3:</strong> The dialog in the &quot;Devices&quot; tab waits for the result, shows &quot;Can not delete device &lt;device&gt;&quot; if something goes wrong, and also works for instances from <code>wled.10</code> upwards (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/914" target="_blank" rel="noreferrer">#914</a>).</p><p><strong>From v0.9.3:</strong> &quot;Discover new devices&quot; first stops the running search and then starts a new one. Searches no longer run side by side (<a href="https://github.com/DrozmotiX/ioBroker.wled/issues/905" target="_blank" rel="noreferrer">#905</a>).</p><p><strong>See also:</strong> <a href="./../erste-schritte/erstes-geraet#adapter-wled-devices-automatically">How and when does the adapter find my WLED devices automatically?</a> · <a href="./../erste-schritte/erstes-geraet#add-device-manually-ip-if">How do I add a device manually by IP?</a></p><p><a id="deal-switched-off-offline-devices"></a></p><h2 id="how-do-i-deal-with-devices-that-are-switched-off-or-offline-and-how-do-i-get-rid-of-the-log-messages" tabindex="-1">How do I deal with devices that are switched off or offline, and how do I get rid of the log messages? <a class="header-anchor" href="#how-do-i-deal-with-devices-that-are-switched-off-or-offline-and-how-do-i-get-rid-of-the-log-messages" aria-label="Permalink to &quot;How do I deal with devices that are switched off or offline, and how do I get rid of the log messages?&quot;">​</a></h2><p><em>This section is still being written.</em></p><p><a id="happens-commands-sent-switched-off"></a></p><h2 id="what-happens-to-commands-sent-to-a-device-that-is-switched-off" tabindex="-1">What happens to commands sent to a device that is switched off? <a class="header-anchor" href="#what-happens-to-commands-sent-to-a-device-that-is-switched-off" aria-label="Permalink to &quot;What happens to commands sent to a device that is switched off?&quot;">​</a></h2><p><em>This section is still being written.</em></p>',33)])])}const m=t(d,[["render",n]]);export{p as __pageData,m as default};
